using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using System.Linq;using System.IO;using System.Text;using EchoProtocol.Echo;using EchoProtocol.Puzzle;using EchoProtocol.Horror;
internal class CommandScript:IRunCommand {
 StringBuilder s=new StringBuilder();int passed,failed;
 void Check(bool ok,string m){if(ok)passed++;else failed++;s.AppendLine((ok?"PASS ":"FAIL ")+m);}
 public void Execute(ExecutionResult result){
 var all=SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();
 var hub=all.First(t=>t.name=="R1 Clinical Observation Hub").gameObject;bool old=hub.activeSelf;hub.SetActive(true);Physics.SyncTransforms();
 int floorCount=0,missing=0;foreach(var bounds in new[]{new Vector4(-10.15f,-4.3f,25.2f,30),new Vector4(-8.95f,-4.05f,30.2f,44.55f),new Vector4(-16.95f,-4.05f,44.65f,47.95f)})for(float x=bounds.x;x<bounds.y;x+=.15f)for(float z=bounds.z;z<bounds.w;z+=.15f){floorCount++;if(!Physics.Raycast(new Vector3(x,.08f,z),Vector3.down,.4f,~0,QueryTriggerInteraction.Ignore))missing++;}Check(missing==0,"continuous floor "+floorCount+" samples missing="+missing);
 foreach(var n in new[]{"P3 A observation glass","P3 opaque separation","P3 B observation glass","P3 lane west boundary","P3 alternative east boundary","P3 recording lane terminal wall","P3 distant hub sealed glazing","P3 long return north wall","P3 long return west end","P3 long return east end","R2 R1 north sealed glass"}) {var col=all.First(t=>t.name==n).GetComponent<Collider>();var b=col.bounds;int count=0,miss=0;bool alongX=b.size.x<b.size.z;for(float h=.15f;h<2.9f;h+=.3f)for(float v=(alongX?b.min.z:b.min.x)+.05f;v<(alongX?b.max.z:b.max.x)-.04f;v+=.15f){var origin=alongX?new Vector3(b.min.x-.3f,h,v):new Vector3(v,h,b.min.z-.3f);count++;if(!col.Raycast(new Ray(origin,alongX?Vector3.right:Vector3.forward),out var hit,1))miss++;}Check(miss==0,n+" boundary rays="+count+" missing="+miss);}
 foreach(var n in new[]{"P3 Gate A alternative route solid panel","P3 Gate B final hold solid panel"}) {var c=all.First(t=>t.name==n).GetComponent<Collider>();int miss=0;for(float x=-6.15f;x<-3.96f;x+=.1f)for(float y=.2f;y<2.7f;y+=.25f)if(!c.Raycast(new Ray(new Vector3(x,y,c.bounds.min.z-.2f),Vector3.forward),out var hit,.5f))miss++;Check(miss==0,n+" closed cross section misses="+miss);}
 foreach(var c in all.SelectMany(t=>t.GetComponents<MonoBehaviour>()).Where(c=>c!=null&&(c is VS1RecallAnchor||c is RecombinationRelay||c is OpticalReader||c is VS1RecoveryHubGate||c is VS1OmittedPassageEvent))) {var so=new SerializedObject(c);var it=so.GetIterator();while(it.NextVisible(true))if(it.propertyType==SerializedPropertyType.ObjectReference)Check(it.objectReferenceValue!=null,c.name+"."+it.propertyPath);}
 var loop=Object.FindFirstObjectByType<LoopController>();var arr=new SerializedObject(loop).FindProperty("resetTargets");for(int i=0;i<arr.arraySize;i++)Check(arr.GetArrayElementAtIndex(i).objectReferenceValue is ILoopResettable,"reset target "+i);
 hub.SetActive(old);Physics.SyncTransforms();s.AppendLine("TOTAL passed="+passed+" failed="+failed);File.WriteAllText("/tmp/echo-vs1-r2/geometry.txt",s.ToString());result.Log(s.ToString());
 }
}
